template:
@php
    // A row with neither a picture nor a name has nothing to show.
    $shown = array_values(array_filter(is_array($logos) ? $logos : [], static fn ($item): bool => is_array($item) && (! empty($item['logo']['url']) || trim((string) ($item['name'] ?? '')) !== '')));
    $label = $heading ? wx_text($heading)->plain() : null;
@endphp
@if ($shown)
<section class="b-logos" data-wx-block="logos">
    @if ($heading)
        <h2 class="b-logos__heading">{{ $heading }}</h2>
    @endif
    <x-webx-slider variant="logos" :label="$label">
        @foreach ($shown as $item)
            @php
                $picture = is_array($item['logo'] ?? null) && ! empty($item['logo']['url']) ? $item['logo'] : null;
                $name = trim((string) ($item['name'] ?? '')) ?: (string) ($picture['alt'] ?? '');
                $link = is_array($item['link'] ?? null) && ! empty($item['link']['url']) && ($item['link']['available'] ?? true) !== false ? $item['link'] : null;
            @endphp
            <x-webx-slide>
                @if ($link)
                    <a class="b-logos__item" href="{{ $link['url'] }}" @if (! empty($link['new_tab'])) target="_blank" @endif @if (! empty($link['rel'])) rel="{{ $link['rel'] }}" @endif>
                @else
                    <span class="b-logos__item">
                @endif
                @if ($picture)
                    <img class="b-logos__logo" src="{{ $picture['url'] }}" alt="{{ $name }}" @if ($picture['width']) width="{{ $picture['width'] }}" height="{{ $picture['height'] }}" @endif>
                @else
                    <span class="b-logos__name">{{ $name }}</span>
                @endif
                @if ($link)
                    </a>
                @else
                    </span>
                @endif
            </x-webx-slide>
        @endforeach
    </x-webx-slider>
</section>
@endif

styles:
.b-logos {
    container-type: inline-size;
}

.b-logos__heading {
    margin: 0 0 1em;
    text-align: center;
}

/* A slide of the strip: the logo in the middle of it, the link as tall as a finger. */
.b-logos__item {
    display: flex;
    align-items: center;
    justify-content: center;
    box-sizing: border-box;
    height: 100%;
    min-height: 4em;
    padding: 0.5em;
    color: inherit;
    text-decoration: none;
}

/* Logos come in every shape: held to one height, never wider than their slide. */
.b-logos__logo {
    display: block;
    width: auto;
    max-width: 100%;
    min-width: 0;
    height: 2.5em;
    object-fit: contain;
    opacity: 0.8;
    transition: opacity 0.2s;
}

a.b-logos__item:hover .b-logos__logo,
a.b-logos__item:focus-visible .b-logos__logo {
    opacity: 1;
}

.b-logos__name {
    font-weight: 600;
    text-align: center;
    white-space: nowrap;
    opacity: 0.8;
}
